import pandas as pdimport requestsimport timeDISCORD_WEBHOOK_URL = "https://discord.com/api/webhooks/1562398893419790368/17LBTw7T9L0KOjhEtMnjmg1UQuwRpv03zZ5AiSXbSH4OY3yuy_an9F6Sr4jUzJsiTXqf"# --- SIMULATORE PORTAFOGLIO ---initial_balance = 100.0  # Capitale iniziale di 100€current_balance = 100.0in_position = Falseentry_price_pos = 0.0position_size = 0.0trailing_stop = 0.0def send_discord_notification(message):    payload = {"content": message}    try:        requests.post(DISCORD_WEBHOOK_URL, json=payload)    except Exception as e:        print(f"Errore Discord: {e}")def get_binance_data():    url = "https://api.binance.com/api/v3/klines?symbol=BTCUSDT&interval=4h&limit=250"    res = requests.get(url).json()        df = pd.DataFrame(res, columns=[        'timestamp', 'open', 'high', 'low', 'close', 'volume',        'close_time', 'qav', 'num_trades', 'taker_base_vol', 'taker_quote_vol', 'ignore'    ])    df['close'] = df['close'].astype(float)    df['high'] = df['high'].astype(float)    df['low'] = df['low'].astype(float)    return dfdef calculate_indicators(df):    df['upper_band'] = df['high'].shift(1).rolling(window=20).max()    df['lower_band'] = df['low'].shift(1).rolling(window=10).min()    df['ema_200'] = df['close'].ewm(span=200, adjust=False).mean()    return dfdef check_signals():    global current_balance, in_position, entry_price_pos, position_size, trailing_stop        df = get_binance_data()    df = calculate_indicators(df)        current = df.iloc[-1]    close_price = current['close']    upper = current['upper_band']    lower = current['lower_band']    ema200 = current['ema_200']        timestamp_str = time.strftime('%H:%M:%S')    print(f"[{timestamp_str}] BTC: ${close_price:.2f} | Saldo Virtuale: €{current_balance:.2f} | Posizione: {in_position}")    # Se siamo in posizione, verifichiamo se scatta il Trailing Stop (uscita)    if in_position:        # Aggiorna il trailing stop se il mercato sale        if lower > trailing_stop:            trailing_stop = lower                    # Controllo uscita (se il prezzo scende sotto il trailing stop)        if close_price <= trailing_stop:            # Calcolo profitto/perdita            pnl_pct = (trailing_stop - entry_price_pos) / entry_price_pos            profit_loss = position_size * pnl_pct            current_balance += profit_loss                        msg = (                f"🛑 **CHIUSURA POSIZIONE (TRAILING STOP)** 🛑\n"                f"**Prezzo Uscita:** ${trailing_stop:.2f}\n"                f"**Risultato Operazione:** {'+' if profit_loss >= 0 else ''}€{profit_loss:.2f} ({pnl_pct*100:.2f}%)\n"                f"💼 **Nuovo Saldo Virtuale:** €{current_balance:.2f}"            )            send_discord_notification(msg)            in_position = False    # Se NON siamo in posizione, cerchiamo il segnale di ingresso    elif not in_position:        if close_price > upper and close_price > ema200:            entry_price_pos = close_price            position_size = current_balance  # Investe tutto il saldo virtuale disponibile            trailing_stop = lower            in_position = True                        msg = (                f"🚀 **NUOVO TRADE APERTO (LONG) BTC/USDT** 🚀\n"                f"**Capitale Investito:** €{position_size:.2f}\n"                f"**Prezzo Ingresso:** ${entry_price_pos:.2f}\n"                f"**Filtro Macro Trend (EMA 200):** ${ema200:.2f}\n"                f"**Trailing Stop Iniziale:** ${trailing_stop:.2f}\n"                f"💼 **Saldo Attuale:** €{current_balance:.2f}"            )            send_discord_notification(msg)if __name__ == "__main__":    send_discord_notification(f"🤖 **Bot Trading 100€ Virtuali Avviato!**\n💼 **Capitale Iniziale:** €{current_balance:.2f}")    while True:        try:            check_signals()            time.sleep(900)  # Controlla ogni 15 minuti        except Exception as e:            print(f"Errore: {e}")            time.sleep(60)